def compute(vars):
    dividends_2018 = vars["v1"]
    dividends_2019 = vars["v2"]
    difference = dividends_2019 - dividends_2018
    return {
        "value": difference,
        "trace": {
            "dividends_2018": dividends_2018,
            "dividends_2019": dividends_2019,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
